            <DropdownMenuItem
              onSelect={() => {
                const nome = prompt('Nome do novo setor');
                if (nome !== null) createSetor(nome);
              }}
              className="rounded-lg cursor-pointer focus:bg-[#57715B]/10 focus:text-[#57715B]"
            >
              <Layers className="mr-2 h-4 w-4" /> Novo Setor
            </DropdownMenuItem>
            <div className="px-2 py-1.5">
              <Select
                value={selectedSetorToDelete}
                onValueChange={(val) => {
                  if (
                    val &&
                    confirm(
                      `Tem certeza que deseja excluir o setor ${val}?`,
                    )
