// ── C. atualizarProdutoSetorUnidade ────────────────────────────────────────

describe('atualizarProdutoSetorUnidade', () => {
  it('chama update em produtos_master com setor e unidade_medida — nenhum outro campo', async () => {
    const updateSpy = vi.fn().mockReturnValue({
      eq: vi.fn().mockResolvedValue({ error: null }),
    });

    const produtosMasterChain: Record<string, unknown> = {
      select: vi.fn().mockReturnThis(),
      eq: vi.fn().mockReturnThis(),
      order: vi.fn().mockReturnThis(),
      update: updateSpy,
      then: (resolve: (v: unknown) => unknown) =>
        Promise.resolve({ data: [], error: null }).then(resolve),
    };

    // setores chain para a query inicial do hook
    const setoresChain = makeChain({ data: [], error: null });

    setupFromMock({
      produtos_master: produtosMasterChain,
      setores: setoresChain,
    });

    const { result } = renderHook(() => useSetores(), {
      wrapper: createWrapper(),
    });

    await act(async () => {
      await result.current.atualizarProdutoSetorUnidade(
        42,
        'EMBALAGENS',
        'un',
      );
    });

    // update deve ter sido chamado SOMENTE com setor e unidade_medida
    expect(updateSpy).toHaveBeenCalledWith({
      setor: 'EMBALAGENS',
      unidade_medida: 'un',
    });

    // garantir que não foi chamado com campos como ativo, nome ou outros
    const chamadaArgs = updateSpy.mock.calls[0][0] as Record<string, unknown>;
    expect(Object.keys(chamadaArgs)).toHaveLength(2);
    expect(chamadaArgs).not.toHaveProperty('ativo');
  });

  it('retorna ok:true em caso de sucesso', async () => {
    const produtosMasterChain: Record<string, unknown> = {
      select: vi.fn().mockReturnThis(),
      eq: vi.fn().mockReturnThis(),
      order: vi.fn().mockReturnThis(),
      update: vi.fn().mockReturnValue({
        eq: vi.fn().mockResolvedValue({ error: null }),
      }),
      then: (resolve: (v: unknown) => unknown) =>
        Promise.resolve({ data: [], error: null }).then(resolve),
    };

    setupFromMock({
      produtos_master: produtosMasterChain,
      setores: makeChain({ data: [], error: null }),
    });

    const { result } = renderHook(() => useSetores(), {
      wrapper: createWrapper(),
    });

    let resultado: Awaited<
      ReturnType<typeof result.current.atualizarProdutoSetorUnidade>
    >;
    await act(async () => {
      resultado = await result.current.atualizarProdutoSetorUnidade(
        1,
        'INSUMOS',
        'kg',
      );
    });

    expect(resultado!.ok).toBe(true);
  });
});

